__NUXT_JSONP__("/how-to-apply/others", {data:[{details:{slug:"en",pageTitle:"Others | Mentor Language Institute",pageDescription:"Thank you for your interest in applying to MLI. This page is for those who already have any visa status other than a student visa, or who are from ESTA Countries or Tourist Visa Countries.",title:"Others",image:"\u002Fimages\u002Fhow-to-apply\u002Fapply-others\u002Fapply-others.jpg",subtitle:["Thank you for your interest in applying to MLI.\u003Cbr \u002F\u003EThis page is for those who already have any visa status other than a student visa, or who are from ESTA Countries or Tourist Visa Countries.","If you plan to apply to MLI without obtaining a student (F-1) visa, please proceed with your enrollment from this page."],applyOnline:{imageLink:{image:"\u002Fimages\u002Fcommon\u002Fapply-now-en.jpg",link:"\u002Fen\u002Fadmission"}},applicationSteps:{title:"Application Steps",description:["Your application steps are different based on your country, nationality, courses and visas, etc. \u003Cb\u003EOur staff will guide you on the exact steps once you submit your on-line application.\u003C\u002Fb\u003E"]},needHelp:{title:"Need help? Ask Us!",description:["- Can I study at MLI without obtaining a visa?\u003Cbr \u002F\u003E- Is it possible to enroll with a different visa other than a student visa(F-1)?\u003Cbr \u002F\u003E- How long can I stay in the U.S. without a student visa?\u003Cbr \u002F\u003E- How many hours per week should I study at MLI in order to obtain a student visa?","The answers to these questions are explained on the website for the U.S. Embassy or U.S. Citizenship and Immigration Services(USCIS).","If you want clarification before submitting your application, please confirm on the web-sites or \u003Cb\u003Efeel free to contact us. We can advise you in 8 languages!\u003C\u002Fb\u003E"]},contactUs:{image:"\u002Fimages\u002Fcommon\u002Fcontact-us-en.png",link:"\u002Fen\u002Fcontact",title:"Contact Us",lists:[{campus:"＜WESTWOOD CAMPUS＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"Tel:310⁻887⁻0777"},{campus:"＜HOLLYWOOD CAMPUS＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"Tel:323⁻870⁻7102"}]},dir:"\u002Fothers",path:"\u002Fothers\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:30.017Z",updatedAt:"2025-05-26T12:06:27.833Z"}}],fetch:{},mutations:void 0});